/* ===== Layer 4 rev 4 mock-up · Portfolio (six owner-approved tabs), Sites directory, Financials root, pilot request ===== */
const PTABS = [['Overview','portfolio'],['Outcomes by site','portfolio/outcomes-by-site'],['Demand and capacity','portfolio/demand-and-capacity'],['Act first','portfolio/act-first'],['What changed','portfolio/what-changed'],['Scope & coverage','portfolio/scope']];
const ptabs = s => tabRow(PTABS,s.ptab||s.id);
const sec = (title,body,sub='',right='',id='') => `<section class="panel"${id?` id="${id}"`:''}><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`;
const region = (label,html) => `<div class="table-wrap scroll-region" tabindex="0" role="region" aria-label="${escapeHtml(label)}">${html}</div>`;
const siteLink = sk => link(`site/${sk}`,SK[sk].name,'strong');

/* ---------- factor table (outcome → factors → leaves; plan against October at every factor) ---------- */
const BOUND = {off:['Outside its limit','red'],at:['At its limit','amber'],near:['Near its limit','amber'],ok:['Within its limit','green']};
function devText(n){if(n.obs)return '<span class="muted">observed</span>';
 if(n.plan!=null&&n.actual!=null&&typeof n.plan==='number'){const d=r2(n.actual-n.plan);if(Math.abs(d)<0.005)return 'on plan';return (d>0?'+':'−')+fmtU(Math.abs(d),n.unit);}
 if(n.dev!=null)return (n.dev>0?'+':'−')+fmtU(Math.abs(n.dev),n.unit);return '—';}
function factorTable(sk,opts={}){const rows=[];
 walk(tree(sk),(n,d)=>{if(opts.depth!=null&&d>opts.depth)return;
  const lab=`<div class="fac" style="--d:${d}">${d?'<span class="fac-branch" aria-hidden="true">└</span>':''}<div><b>${n.label}</b>${n.residual?` <span class="badge outline">${n.resLabel||'not explained by the model yet'}</span>`:''}<small>${n.how}</small>${n.bound?`<small class="bnd">${badge(...BOUND[n.bound.state])} ${n.bound.text}</small>`:''}</div></div>`;
  const pl=n.plan!=null?fmtU(n.plan,n.unit):'<span class="muted">not declared</span>';
  const ac=n.actual!=null?fig(`node:${sk}:${n.id}`,fmtU(n.actual,n.unit)):'—';
  rows.push(`<tr class="${n.residual?'resid':''} ${d===0?'root':''}"><th scope="row">${lab}</th><td>${n.obs&&n.plan==null?'<span class="muted">—</span>':pl}</td><td>${ac}</td><td>${devText(n)}</td><td>${n.eff!=null&&!n.obs?(n.evd&&n.actual==null?fig(n.evd,usd(n.eff,true)):usd(n.eff,true)):'—'}</td><td>${ec(n.cls)}</td><td>${n.lens?lensTag(n.lens):''}</td><td>${n.dec?link(`decision/${n.dec}`,'Decision →'):''}</td></tr>`);});
 const cost=OPS[SK[sk].op].kind==='cost';
 return region(`Factor structure for ${SK[sk].name}`,`<table class="ftab"><thead><tr><th>Factor and how it composes</th><th>Plan</th><th>October</th><th>Deviation</th><th>Effect on ${cost?'cost (+ lower)':'contribution'}</th><th>Evidence</th><th>Outcome</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table>`);}

/* ---------- value chain strip (stages with leaks between them) ---------- */
function chainStrip(op,sk){const o=OPS[op];let st;
 if(o.vertical==='mini'){const C=sk?{...siteM(sk).period.actual,plan_billed_kwh:siteM(sk).period.plan.billed_kwh,plan_revenue:siteM(sk).period.plan.revenue}:o.t.portfolio.chain;
  const loss=sk?(C.technical_loss_kwh??C.expected_technical_loss_kwh)+(C.unexplained_kwh||0):C.delivered_kwh-C.metered_kwh,unb=sk?(C.adjustments_kwh+(C.unbilled_mapping_kwh||0)):C.metered_kwh-C.billed_kwh;
  st=[['Usable capacity','Not available yet','needs the energy management export by time window','na'],['leak','idle capacity: not available yet'],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',`losses ${num(loss)} kWh`],['Metered',num(C.metered_kwh)+' kWh','Measured'],['leak',`adjustments and unmapped meters ${num(unb)} kWh`],
   ['Billed',num(C.billed_kwh)+' kWh',`plan ${num(C.plan_billed_kwh)} · Recorded`],['leak',''],['Revenue',usd(C.revenue),`plan ${usd(C.plan_revenue)} · Recorded`],['leak',`in transit ${usd(C.in_transit)} · outstanding ${usd(C.outstanding)}`],['Cash collected',usd(C.collected),'Recorded']];}
 else if(o.vertical==='cold'){const t=o.t,C=sk?{capacity_crate_days:CAPCD(sk),occupied_crate_days:siteM(sk).period.actual.crate_days,plan_crate_days:siteM(sk).period.plan.crate_days,revenue:siteM(sk).period.actual.revenue,plan_revenue:siteM(sk).period.plan.revenue,collected:siteM(sk).period.actual.collected,outstanding:siteM(sk).period.actual.outstanding}:t.portfolio.chain;
  st=[['Capacity',num(C.capacity_crate_days)+' crate-days','Recorded'],['leak',`idle ${num(C.capacity_crate_days-C.occupied_crate_days)} crate-days`],['Occupied',num(C.occupied_crate_days)+' crate-days',`plan ${num(C.plan_crate_days)} · Recorded`],['leak','no incompatible or off-rate-card occupancy recorded'],['Chargeable',num(C.revenue/t.prices.storage_usd_per_crate_day)+' crate-days','Calculated from records (ledger to invoice reconciliation)'],['leak','no ledger-to-invoice difference in October'],['Invoiced',usd(C.revenue),`plan ${usd(C.plan_revenue)} · Recorded`],['leak',`outstanding ${usd(C.outstanding)}`],['Received',usd(C.collected),'Recorded']];}
 else {const C=sk?{delivered_kwh:siteM(sk).period.actual.kwh,departures_required:siteM(sk).period.actual.departures_required,departures_met:siteM(sk).period.actual.departures_met}:o.t.portfolio.chain;const dl=sk==='ruiru'?[`${num(NV('ruiru','actual','deliverable_kwh_night'))} kWh a night`,`from the depot structure, at the ${siteM('ruiru').physical.import_limit_kw} kW import limit`]:sk==='kasarani'?[`${num(KN().deliverable_kwh_night)} of ${num(KN().required_kwh_night)} kWh a night`,'since 1 Nov, calculated from records; full in October']:['Not available yet','needs the depot charging model per night'];
  st=[['Deliverable energy',dl[0],dl[1],sk?'':'na'],['leak',''],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',''],['Required departures',num(C.departures_required),'Recorded (roster)'],['leak',`missed in October: ${num(C.departures_required-C.departures_met)}`],['Departures met',num(C.departures_met),'Recorded'],['leak',''],['Revenue','Not applicable','charging is a cost centre','na']];}
 const html=st.map(x=>x[0]==='leak'?`<li class="leak" aria-label="Leak: ${escapeHtml(x[1]||'none recorded')}"><span>${x[1]||'—'}</span></li>`:`<li class="stage ${x[3]==='na'?'na':''}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></li>`).join('');
 return `<figure class="chainfig"><figcaption><strong>${sk?SK[sk].name:o.name} value chain, October</strong> · stages are factors; the gaps between them are leaks</figcaption><ol class="chain">${html}</ol></figure>`;}

/* ---------- Overview ---------- */
function headline(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,res=residualOf(op);
 if(o.kind==='cost')return `October charging and depot cost, composed from the depots’ factors: ${usd(T.actual)} against a plan of ${usd(T.plan)}, ${usd(-T.variance)} over. All ${num(P.departures_met)} required departures were met, at ${usd2(P.cost_per_departure_actual)} each (plan ${usd2(r2(T.plan/P.departures_required))}).`;
 const c=P.chain;return `October contribution, composed from the sites’ factors: ${usd(T.actual)} against a plan of ${usd(T.plan)}, ${usd(-T.variance)} short. Revenue factors move it by ${usd(c.revenue_variance,true)}, cost factors by ${usd(c.cost_variance,true)}.`;}
function heroFigs(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,A=P.allocation,res=residualOf(op),cv=P.coverage,M=o.t.portfolio_constraints,crew=derivedPlan(op).crew_visits_limit,used=derivedPlan(op).crew_visits_used;
 const plan=planCase(op);
 const h=(lab,val,note,cls)=>`<div class="hero"><span>${lab}</span><div class="herov">${val}</div><small>${note}</small>${cls?ec(cls):''}</div>`;
 const val=op==='lakeside'?plan.value:op==='harvest'?harvestValue():(derivedPlan('metro').value);
 const m12=h('Modelled 12-month change from the valued options',fig(`port:${op}:m12`,val===0?'$0':usd(val,true)),op==='harvest'?'Valued options only; includes an assumed recovery share (80%) at Kirinyaga':'Valued options only; includes design values not yet run on site data','MODELLED');
 return `<div class="heroes">${h(o.kind==='cost'?'Charging and depot cost':'Contribution',fig(`port:${op}:actual`,usd(T.actual)),`plan ${usd(T.plan)} · ${fig(`port:${op}:cov`,pct(cv.cost_recorded_share,1))} of cost recorded`,'RECORDED')}
 ${h('Deviation, attributed to factors',fig(`port:${op}:variance`,usd(T.variance,true)),`${usd(res.attributed,true)} attributed to factors · ${usd(res.residual,true)} ${op==='metro'?'not attributed yet':'not explained by the model yet'}`,'')}
 ${h('Plan spend',fig(`port:${op}:spend`,usd(plan.spend))+` <small>of ${usd(op==='lakeside'?LS.budget:M.budget_usd_nov_dec)}</small>`,`${num(plan.visits)} of ${num(derivedPlan(op).crew_visits_limit)} ${o.crewWord}`,'QUOTE')}
 ${m12}</div>`;}
/* R9-M4: every figure below is read from the evaluated nodes (DERIVED via applyDerived), bridge rows or manifest fields; none is typed. */
const NV=(sk,side,node)=>DSITE(sk)?.[side]?.nodes?.[node];
const BR=(sk,drv)=>(siteM(sk).period.bridge||[]).find(b=>b.driver===drv);
const BQ=(sk,drv)=>{const b=BR(sk,drv);return b?qtyOf(b.basis):null;};
const sgnK=v=>(v>0?'+':v<0?'−':'')+num(Math.abs(v));
const perCD=sk=>siteM(sk).period.actual.energy/siteM(sk).period.actual.crate_days;
const overPct=sk=>{const a=siteM(sk).period.actual;return (a.kwh-a.kwh_model)/a.kwh_model*100;};
const sumNodes=(op,side,node)=>OPS[op].sites.reduce((a,sk)=>a+(NV(sk,side,node)||0),0);
const CARDS = {
 lakeside:()=>{const c=OPS.lakeside.t.portfolio.chain,hu=OPT['MTO-HULLER'],dv=b=>`${SK[b[0]].name} ${sgnK(b[1].q)} kWh (${usd(b[1].a,true)})`;
  const vol=OPS.lakeside.sites.map(sk=>[sk,(()=>{const b=BR(sk,'DEMAND_VOLUME');return b?{q:Math.sign(b.amount)*qtyOf(b.basis)[0],a:b.amount}:null;})()]).filter(x=>x[1]);
  const cand=BR('kobo','CANDIDATE_RUNNING'),unb=BR('mto','METER_MAPPING_UNBILLED'),kfb=siteM('kobo').period.fuel_balance,ma=siteM('mto').period.actual,ent=siteM('mto').entitlement;
  return {
  grow:{pos:`Revenue ${usd(sumNodes('lakeside','actual','revenue'))} against ${usd(sumNodes('lakeside','plan','revenue'))}`,f:[[`Billed kWh ${num(sumNodes('lakeside','actual','billed_kwh'))} against ${num(sumNodes('lakeside','plan','billed_kwh'))}`,'RECORDED'],[`Customer consumption: ${vol.map(dv).join(', ')}`,'RECORDED'],[`New factor: Mto cooperative’s signed letter of intent, ${num(hu.load.kwh_month)} kWh a month of daytime demand`,'MODELLED']]},
  optimize:{pos:`Cost to serve ${usd(sumNodes('lakeside','actual','cost_to_serve'))} against ${usd(sumNodes('lakeside','plan','cost_to_serve'))}`,f:[[`Diesel litres ${num(sumNodes('lakeside','actual','diesel_l'))} against ${num(sumNodes('lakeside','plan','diesel_l'))}: all of the cost deviation`,'RECORDED'],[`Kobo: ${num(qtyOf(cand.basis)[0])} L of candidate running while solar could carry the load (${usd(cand.amount,true)}); of it, the best feasible option avoids ${num(OPT['KOB-STOPSOC'].forward_replay.avoidable_fuel_l)} L a month (Modelled)`,'DERIVED'],[`Mto: ${num(qtyOf(unb.basis)[0])} kWh metered but not billed after a meter swap (${usd(unb.amount,true)})`,'RECORDED']]},
  protect:{pos:'',f:[]},
  assure:{pos:`${pct(OPS.lakeside.t.portfolio.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Kisiwa’s October maintenance-contract invoice missing: carried at plan','ESTIMATED'],[`Not explained yet: Kobo ${num(kfb.residual_l)} L above the ${kfb.tolerance_pct}% tolerance; Mto ${num(ma.unexplained_kwh)} kWh beyond expected losses (not priced)`,'DERIVED'],['Verified results: none yet; trial not started','MISSING']]}};},
 harvest:()=>{const t=OPS.harvest.t,capc=CAPCD_ALL()/3,mw=siteM('mwea').period,ki=siteM('kirinyaga').period.actual,ag=OPT['MWEA-AGG'],occ=sumNodes('harvest','actual','revenue')/t.prices.storage_usd_per_crate_day,pocc=sumNodes('harvest','plan','revenue')/t.prices.storage_usd_per_crate_day,eff=BR('kirinyaga','ENERGY_EFFICIENCY');
  return {
  grow:{pos:`Revenue ${usd(sumNodes('harvest','actual','revenue'))} against ${usd(sumNodes('harvest','plan','revenue'))}`,f:[[`Occupied crate-days ${num(occ)} against ${num(pocc)}: all at Mwea (${mw.actual.occupancy_pct}% full against ${mw.plan.occupancy_pct}%)`,'RECORDED'],[`Idle capacity ${num(capc*3-occ)} crate-days`,'DERIVED'],[`New factor: aggregator’s draft contract, ${num(ag.economics.crate_days_month/30)} crates December to March`,'MODELLED']]},
  optimize:{pos:`Cost to serve ${usd(sumNodes('harvest','actual','cost_to_serve'))} against ${usd(sumNodes('harvest','plan','cost_to_serve'))}`,f:[[`Kirinyaga electricity ${num(ki.kwh-ki.kwh_model)} kWh (${Math.round(overPct('kirinyaga'))}%) above what occupancy explains (${usd(eff.amount,true)})`,'DERIVED'],[`Mwea within ${overPct('mwea').toFixed(1)}% of its model: high cost per crate-day is low occupancy`,'DERIVED'],[`Electricity per crate-day: Mwea $${perCD('mwea').toFixed(4)}, Kirinyaga $${perCD('kirinyaga').toFixed(4)}`,'DERIVED']]},
  protect:{pos:'',f:[]},
  assure:{pos:`${pct(t.portfolio.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Thika’s October service invoice missing: carried at plan','ESTIMATED'],['Every October deviation attributed to an observed factor: nothing unexplained','DERIVED'],[`Verified results: none yet; witnessed start test after ${fdate(siteM('thika').entitlement.remedy_scheduled)}`,'MISSING']]}};},
 metro:()=>{const P=OPS.metro.t.portfolio,a6=DOPT('RUI-ABSORB6'),em=siteM('embakasi').period,pk=BR('embakasi','PEAK_ENERGY_SHARE'),dm=BR('embakasi','DEMAND_CHARGE'),ru=siteM('ruiru'),ruR=residualOf('metro').residual,ka=siteM('kasarani').incident;
  const cost=sumNodes('metro','actual','cost_to_serve'),dep=sumNodes('metro','actual','departures_met'),req=sumNodes('metro','actual','departures_required'),planCost=opTotals('metro').plan;
  return {
  grow:{pos:'Revenue: not applicable · charging is a cost centre',f:[[`Required departures met: ${num(dep)} of ${num(req)}`,'RECORDED'],[`Ruiru can serve 6 more buses on its chargers: ${num(a6.bound.required_kwh_night)} of ${num(a6.bound.deliverable_kwh_night)} kWh a night`,'MODELLED'],[`Ruiru: ${pct(ru.period.actual.charger_hour_utilisation)} of nameplate charger-hours; ${ruiruDeliverable()} of deliverable energy a night (the ${ru.physical.import_limit_kw} kW import limit binds)`,'DERIVED']]},
  optimize:{pos:`Cost ${usd(cost)} against ${usd(planCost)} · ${usd2(cost/dep)} a departure`,f:[[`Embakasi: ${pct(em.actual.peak_share)} of charging at peak price against ${pct(em.plan.peak_share)} (${usd(pk.amount,true)})`,'RECORDED'],[`Embakasi: monthly peak ${em.actual.max_kw} kW against ${em.plan.max_kw} kW (${usd(dm.amount,true)})`,'RECORDED'],[`Ruiru: ${usd(ruR,true)} not attributed (the plan is declared only as a bill total)`,'DERIVED']]},
  protect:{pos:'',f:[]},
  assure:{pos:`${pct(P.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Kasarani’s October maintenance invoice missing: carried at plan','ESTIMATED'],['Embakasi’s new tariff is an assumption until the invoice confirms it','CONTRACT'],['Verified results: none yet','MISSING']]}};}};
function outcomeCards(op){const C=CARDS[op]();C.protect=protectCard(op);C.optimize.f=[...C.optimize.f,...opsCardLines(op)];return `<div class="ocards">${Object.entries(LENS).map(([k,[name,ico]])=>`<article class="ocard lens-b-${k}"><div class="ocard-h">${icon(ico)}<h3>${name}</h3></div><p class="ocard-pos">${C[k].pos}</p><h4>Factors that define it</h4><ul>${C[k].f.map(([t,c])=>`<li><span>${t}</span>${ec(c)}</li>`).join('')}</ul>${link('portfolio/outcomes-by-site','Open the factor structure →')}</article>`).join('')}</div><p class="note">The four outcomes are read over one factor structure. Different evidence classes sit side by side and are never added; Protect shows measured shortfalls against target with values at stake listed beside; Assure shows the evidence state.</p>`;}
function ATTN_OF(op){const ko=siteM('kobo').period,cand=BR('kobo','CANDIDATE_RUNNING'),mto=siteM('mto'),kfb=ko.fuel_balance,mw=siteM('mwea').period,emb=siteM('embakasi'),ka=siteM('kasarani').incident,ru=siteM('ruiru');
 return {
 lakeside:[['off','Off plan','kobo',`Litres used ${num(ko.actual.diesel_l)} against ${num(ko.plan.diesel_l)} planned; ${num(qtyOf(cand.basis)[0])} L of it is candidate running while solar and the battery could carry the load`,'kobo-generator'],['at','At its limit','kisiwa','Evening supply on one generator at 95% load since generator 1 failed on 30 Oct','kisiwa-genset'],['new','New factor','mto',`The cooperative’s signed letter of intent for a daytime rice huller; it lapses on ${fdate('2026-11-30')}`,'mto-demand'],['due','Deadline','mto',`Inverter 2 failed on ${fdate(mto.entitlement.occurrence.failed)}: half the daytime capacity; warranty notice due ${fdate(mto.entitlement.notice_deadline)}`,'mto-inverter'],['off','Off plan','mto',`${num(mto.period.actual.unbilled_mapping_kwh)} kWh metered but not billed after the 3 Oct meter swap`,'mto-billing'],['unobs','Not explained','kobo',`${num(kfb.residual_l)} L of fuel beyond what the generator model explains (above the ${kfb.tolerance_pct}% tolerance): investigation, no recovery claimed`,'kobo-generator']],
 harvest:[['off','Off plan','mwea',`Occupied crate-days ${num(NV('mwea','actual','revenue')/OPS.harvest.t.prices.storage_usd_per_crate_day)} against ${num(NV('mwea','plan','revenue')/OPS.harvest.t.prices.storage_usd_per_crate_day)} planned (${mw.actual.occupancy_pct}% full against ${mw.plan.occupancy_pct}%)`,'mwea-occupancy'],['off','Off plan','kirinyaga',`Electricity ${Math.round(overPct('kirinyaga'))}% above what its occupancy explains (tolerance ${OPS.harvest.t.energy_model.tolerance_pct}%)`,'kirinyaga-energy'],['at','Limit breached','thika',`A batch was above its 5 °C limit for 20–30 minutes on 6 Oct after the backup failed to start; the controller is replaced on ${fdate(siteM('thika').entitlement.remedy_scheduled)}`,'thika-backup'],['new','New factor','mwea',`The aggregator’s draft contract: ${num(DOPT('MWEA-AGG').params.crates)} crates, December to March`,'mwea-occupancy']],
 metro:[['off','Below its limit','kasarani',`On plan in October. Since 1 Nov charger 2 is down: ${num(KN().deliverable_kwh_night)} of ${num(KN().required_kwh_night)} kWh a night, so departures are at risk; ${num(KN().departures_missed)} missed so far`,'kasarani-charger'],['off','Off plan','embakasi',`${pct(emb.period.actual.peak_share)} of charging at peak price against ${pct(emb.period.plan.peak_share)} planned`,'embakasi-schedule'],['at','At its limit','embakasi',`Monthly peak import ${emb.period.actual.max_kw} kW: at the ${emb.physical.import_limit_kw} kW limit`,'embakasi-schedule'],['new','New factor','embakasi','From 1 Nov the tariff adds a 00:00–05:00 rate at $0.09','embakasi-schedule'],['new','New factor','ruiru','The city offers 6 more buses on a new route','ruiru-expansion'],['near','Near its limit','ruiru',`Peak import ${ru.period.actual.max_kw} kW of a ${ru.physical.import_limit_kw} kW limit`,'ruiru-expansion'],['low','Low','ruiru','Charger 7, connector 2 silent since 6 Oct; no departure depends on it','ruiru-connector']]}[op];}
const ATTN=new Proxy({},{get:(_,op)=>ATTN_OF(op)});
function attentionList(op,sk){const rows=ATTN[op].filter(r=>!sk||r[2]===sk);if(!rows.length)return '<p class="note">No factor at this site is off plan, at a limit or newly appeared.</p>';
 return `<ul class="attn">${rows.map(([k,t,s,txt,d])=>`<li class="attn-${k}"><span class="attn-k">${t}</span><div>${sk?'':`<b>${SK[s].name}</b> · `}${txt}</div>${link(`decision/${d}`,'Decision →')}</li>`).join('')}</ul>`;}
function CONTRAST_OF(op){const ks=siteM('kisiwa').period.actual,ko=siteM('kobo').period.actual,cand=BR('kobo','CANDIDATE_RUNNING'),st=OPT['KOB-STOPSOC'],mw=siteM('mwea').period,ki=siteM('kirinyaga').period.actual,ch=OPT['EMB-CHEAPEST'],dl=OPT['EMB-DEADLINE'];
 return {
 lakeside:[['Kisiwa burns the most diesel and has nothing to save.',`Kisiwa used ${num(ks.diesel_l)} L in October, the most in the portfolio, but every generator interval was needed: a rainy month and evening load larger than solar plus battery. Kobo used ${ko.diesel_l<=ks.diesel_l/2?'half as much':num(ko.diesel_l)+' L'}, yet ${num(qtyOf(cand.basis)[0])} L of its running was candidate running while solar could carry the load; of that, the best feasible option avoids ${num(st.forward_replay.avoidable_fuel_l)} L a month (Modelled), worth ${usd(st.economics.net_12m)} over 12 months.`,'kobo-generator','Kobo’s generator decision']],
 harvest:[['Mwea has the worst cost per crate-day and healthy equipment.',`Mwea’s electricity per crate-day ($${perCD('mwea').toFixed(4)}) is the highest, but it is within ${overPct('mwea').toFixed(1)}% of what its occupancy needs: it is ${mw.actual.occupancy_pct}% full against a ${mw.plan.occupancy_pct}% plan, so the lever is a customer, not a compressor. Kirinyaga looks fine ($${perCD('kirinyaga').toFixed(4)}) but uses ${Math.round(overPct('kirinyaga'))}% more electricity than its ${ki.occupancy_pct}% occupancy explains: there the lever is a ${usd(OPT['KIRI-REPAIR'].cost)} repair.`,'mwea-occupancy','Mwea’s occupancy decision']],
 metro:[['An idle connector ranks below a busy depot’s fault, and the cheapest schedule is rejected.',`Ruiru’s charger 7, connector 2 has been silent since 6 Oct, but no departure depends on it. Kasarani was on plan in October, yet since 1 Nov one bus is short of charge every night: that comes first. At Embakasi the cheapest bill (00:00–05:00 only, ${usd(ch.economics.energy_cost_monthly)} a month) leaves ${ch.buses_short} buses short every night, so the departure-time schedule (${usd(dl.economics.energy_cost_monthly)}) wins.`,'kasarani-charger','Kasarani’s charger decision']]}[op];}
const CONTRAST=new Proxy({},{get:(_,op)=>CONTRAST_OF(op)});
function contrastPanel(op){return sec('Sites that look alike need different levers',CONTRAST[op].map(([h,p,d,l])=>`<article class="contrast"><h3>${h}</h3><p>${p}</p>${link(`decision/${d}`,`Open ${l} →`)}</article>`).join(''));}
function firstMoves(op){const P=planCase(op);return `<section class="moves-strip" aria-labelledby="fm-h"><h2 id="fm-h">The plan’s first three moves</h2><ol>${P.rows.slice(0,3).map(r=>`<li>${link(`decision/${DEC_SEE_ALSO[r.id]||decOf(r.id).id}`,optLabel(r.id))} <small>${SK[OPT[r.id]._site].name}</small></li>`).join('')}</ol>${link('portfolio/act-first','Open the plan →')}</section>`;}
function overviewScreen(){const op=LS.op;return `<div class="headline"><p>${headline(op)}</p></div>${heroFigs(op)}${firstMoves(op)}
 <details class="chain-disc" ${window.innerWidth>760?'open':''}><summary>Value chain, October</summary>${chainStrip(op)}</details>
 <h2 class="h2s">Each outcome and the factors that make it</h2>${outcomeCards(op)}
 <div class="grid2">${sec('Factors needing attention',attentionList(op),'Off plan, at or near an obligation limit, or newly appeared. Seen at the factor before the books show it.')}<div>${contrastPanel(op)}</div></div>`;}

/* ---------- Act first: the plan under budget and crews, with switches ---------- */
const WHY_FIRST = {'KIS-REPAIR':'Must do: evening supply has no backup','KOB-STOPSOC':'Value: less generator running after dawn; remote change','MTO-INV-CLAIM':`Deadline: warranty notice by ${fdate(siteM('mto').entitlement.notice_deadline)}; the huller depends on it`,'MTO-INV-BUYNOW':`Deadline: the huller’s letter of intent lapses ${fdate(siteM('mto').decision.options.find(x=>x.id==='MTO-HULLER').customer_loi.lapses)}`,'MTO-HULLER':'Value: new paying daytime demand','MTO-BILLING':'Value: restores billed charges; office work','MTO-METER-AUDIT':`Evidence: ${num(siteM('mto').period.actual.unexplained_kwh)} kWh not explained yet`,'BAT-EVIDENCE':`Protects ${usd(OPS.lakeside.t.portfolio.allocation.listed_not_summed['BAT-001_cover_exposure'])} of cover; nothing breaks if it waits a month`,
 'THIKA-EPC-STOPGAP':'Must do: no action fails the batch temperature limit (days with the backup start unproven)','KIRI-REPAIR':'Value: recovers the room’s excess energy','MWEA-AGG':'Value: new customer, conditional on signature','KAS-OEM-STOPGAP':'Must do: no action fails the departures limit (departures missed)','EMB-DEADLINE':'Value: lower charging bill under the November tariff','RUI-ABSORB6':'Contract decision for the city'};
const VW=(id,w,extra='')=>{const n=DOPT(id)?.crew_visits??0;return `${num(n)} ${w}${n===1?'':'s'}${extra}`;};
const VISIT = {'KIS-REPAIR':[()=>VW('KIS-REPAIR','crew visit'),'field'],'MTO-INV-CLAIM':[()=>VW('MTO-INV-CLAIM','crew visit',' (meter check on the same visit)'),'field'],'MTO-INV-BUYNOW':[()=>VW('MTO-INV-BUYNOW','crew visit',' (meter check on the same visit)'),'field'],'BAT-EVIDENCE':[()=>VW('BAT-EVIDENCE','crew visit'),'field'],'KOB-STOPSOC':[()=>'Remote: vendor change + supervised trial','remote'],'MTO-HULLER':[()=>`Connection contractor (in the ${usd(DOPT('MTO-HULLER').net_one_off)})`,'contractor'],'MTO-BILLING':[()=>'Office: billing records','remote'],'MTO-METER-AUDIT':[()=>'On the inverter visit','field'],
 'THIKA-EPC-STOPGAP':[()=>'Site staff: night rota + SMS alarm','remote'],'KIRI-REPAIR':[()=>VW('KIRI-REPAIR','technician visit'),'field'],'MWEA-AGG':[()=>VW('MWEA-AGG','technician visit',' (ethylene curtain)'),'field'],'KAS-OEM-STOPGAP':[()=>'Operations: one bus to Ruiru each night','remote'],'EMB-DEADLINE':[()=>'Remote: charger management schedule','remote'],'RUI-ABSORB6':[()=>'Contract: no technician work','remote']};
const PLAN_EFFECT={'MTO-INV-CLAIM':()=>[usd(-OPT['MTO-INV-CLAIM'].residual_cost),'our cost, counted in the plan’s 12-month change'],'MTO-INV-BUYNOW':()=>[usd(-OPT['MTO-INV-BUYNOW'].residual_cost),'our cost, counted in the plan’s 12-month change'],'BAT-EVIDENCE':()=>[`Protects ${usd(OPS.lakeside.t.portfolio.allocation.listed_not_summed['BAT-001_cover_exposure'])} of cover`,'at stake, not money; no saving claimed']};
const harvestValue=()=>derivedPlan('harvest').value;
const ruiruDeliverable=()=>Math.round(OPS.metro.t.portfolio.operations.measures.find(m=>m.id==='deliverable_energy_used').sites_pct.Ruiru)+'%';
const inv0=c=>c.items.find(i=>/^MTO-INV-/.test(i));
function mtoCapacityLine(){const h=id=>num(DOPT(id).protect.obligation_hours_without_redundancy);return `Reduced daytime capacity from ${fdate(AS_OF)} to ${fdate(DERIVED.horizons.protect_horizon_end)}: claim and wait ${h('MTO-INV-CLAIM')} h, buy now ${h('MTO-INV-BUYNOW')} h (Protect; the switch itself is decided on money).`;}
const DVTEXT='Design value: the replay has not yet been run on site data';
const dvTag=(t=DVTEXT)=>`<span class="dv">${t}</span>`;
const SHORT={'KOB-STOPSOC':'Kobo stop setting','MTO-HULLER':'Mto rice huller','MTO-INV-CLAIM':'Mto inverter claim','MTO-INV-BUYNOW':'Mto inverter bought now','KIRI-REPAIR':'Kirinyaga repair','MWEA-AGG':'Mwea contract','EMB-DEADLINE':'Embakasi schedule','KAS-OEM-STOPGAP':'Kasarani cover','KIS-REPAIR':'Kisiwa repair','BAT-EVIDENCE':'Kobo battery evidence','THIKA-EPC-STOPGAP':'Thika night cover'};
function valueNote(op,P){const dp=derivedPlan(op),nv=dp.items.filter(i=>!dp.valued_options.includes(i));
 const v=dp.valued_options.map(id=>`${SHORT[id]||optLabel(id)} ${usd(DOPT(id).value,true)}${id==='KAS-OEM-STOPGAP'?` (penalties avoided ${usd(DOPT(id).monthly_or_horizon_change)} − ${usd(DOPT(id).operator_one_off)})`:''}`);
 return `${v.length?`From the valued options: ${v.join(', ')}, net of their operator-borne one-off costs (${usd(dp.valued_option_costs)}).`:'No valued option in this case.'}${op==='harvest'&&dp.valued_options.includes('MWEA-AGG')?' The Mwea contract’s 4 months fall inside the 12-month horizon.':''} Not valued in money: ${usd(dp.not_valued_in_money)}${nv.length?`, with its effect on Protect: ${nv.map(id=>`${SHORT[id]} (${usd(DOPT(id).operator_one_off)}): ${protectEffectLine(id)}`).join('; ')}`:''}.${op==='metro'?` Ruiru’s 6 extra buses are listed beside, not added (a different comparator).`:''}`;}
const DEFAULT_CASE = op => op==='lakeside'?(LS.budget===5000&&LS.loi):op==='harvest'?LS.agg:LS.tou;
function downside(op){const D=OPS[op].t.portfolio.allocation.downside,o=D.others||{};
 const others=op==='lakeside'?` Other sensitivities: diesel 20% cheaper ${usd(o.diesel_minus_20pct,true)}; only 160 L a month feasible ${usd(o.feasible_fuel_160l,true)}.`:op==='harvest'?` Other sensitivity: Kirinyaga recovery at 60% ${usd(o.kirinyaga_recovery_60pct,true)}.`:'';
 const s=`${D.value===0?'$0':usd(D.value,true)} if ${D.sensitivity.replace('(huller drops)','(the huller drops)').replace("Embakasi's","Embakasi’s").replace(' (flat tariff)',' (a flat tariff)')}.${others}`;
 return DEFAULT_CASE(op)?`Downside: ${s} ${ec('MODELLED')}`:`Downside shown for the default plan: ${s} ${ec('MODELLED')}`;}
function planValueRecord(op){const o=OPS[op],A=o.t.portfolio.allocation,P=planCase(op);
 const vo=derivedPlan(op).valued_options; /* rev 13 F1: the rows are the evaluated case's valued options */
 const rows=vo.map(id=>[optLabel(id),usd(DOPT(id).value,true)]);
 const val=derivedPlan(op).value;
 const ks=DOPT('KOB-STOPSOC').params,hu=DOPT('MTO-HULLER'),parts=[]; /* rev 13 F1: only the valued options in this case, read from the evaluated params */
 if(vo.includes('KOB-STOPSOC'))parts.push(`the generator stop setting (${num(ks.avoided_candidate_l)} L a month avoided; dawn charge below 35% on ${num(ks.dawn_days_below_35pct)} replayed days)`);
 if(vo.includes('MTO-HULLER'))parts.push(`the rice huller (${num(hu.params.added_fuel_l)} L of extra fuel, ${usd(hu.monthly_or_horizon_change)} a month)`);
 if(vo.includes('EMB-DEADLINE'))parts.push(`the Embakasi schedule (${num(DOPT('EMB-DEADLINE').params.feasible_nights)} of ${num(DSITE('embakasi').actual.nodes.nights_in_period)} October nights feasible in the replay)`);
 const dvwhat=parts.join(' and ');
 const hasDV=op==='harvest'?vo.includes('KIRI-REPAIR'):parts.length>0;
 return {title:'Modelled 12-month change from the valued options',value:usd(val,true),cls:'MODELLED',def:`${op==='lakeside'?'':'Net of the valued options’ own one-off costs. '}${valueNote(op,P)} ${!hasDV?'':op==='harvest'?dvTag('Assumption: Kirinyaga recovery share 80%, range 60–90%')+'; no replay is involved.':dvTag()+': includes '+dvwhat+'.'}`,formula:`Plan value = Σ of the valued options’ changes against no action, each evaluated through the structure (contribution or cost to serve) and enumerated under the switches: ${derivedPlan(op).valued_options.map(id=>`${optLabel(id)} ${usd(DERIVED.options[id].value,true)}`).join(' + ').replace(/\+ −/g,'− ')||'no valued option'} = ${usd(derivedPlan(op).value,true)}`,parts:[],sys:op==='harvest'?'Option valuations from the repair quote, the recovery assumption and the draft contract terms':SRCDEF.model[0],head:'valued option, 12-month result',rows,prov:op==='harvest'?'source-emulated':'demo-simulated',clocks:[['Horizon','12 months from the change'],['Prices','October prices and contracts']],coverage:`Modelled, not realised. ${downside(op).replace(/<[^>]+>/g,'').trim()}`,path:`tenants[${o.ti}].portfolio.allocation`};}
function planCase(op){const o=OPS[op],A=o.t.portfolio.allocation,M=o.t.portfolio_constraints;
 if(op==='lakeside'){const SC=DERIVED.plans['lakeside-power'].switch_cases,key=`${LS.budget}/${LS.loi?'True':'False'}`,c=SC[key],inv=x=>x.items.find(i=>/^MTO-INV-/.test(i)),hul=x=>x.items.includes('MTO-HULLER');
  /* Rev 13: the case's items, inverter path and huller come from the evaluated switch case; the competing path is the evaluated case (same letter switch first) that takes the other inverter option */
  const ids=[...c.items],mine=inv(c),others=Object.entries(SC).filter(([,x])=>inv(x)!==mine).sort(([a],[b])=>(b.endsWith(LS.loi?'True':'False')?1:0)-(a.endsWith(LS.loi?'True':'False')?1:0)||+a.split('/')[0]-+b.split('/')[0]);
  const asPath=x=>({id:inv(x),value:x.value,spend:x.spend,huller:hul(x),case:x});
  const win=asPath(c),lose=others.length?asPath(others[0][1]):null;
  return {key,spend:c.spend,value:c.value,visits:c.crew_visits_used,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]})),win,lose,loseAffordable:lose?lose.spend<=LS.budget:false,huller:hul(c),c};}
 if(op==='harvest'){const ids=[...derivedPlan('harvest').items];return {spend:derivedPlan('harvest').spend,visits:derivedPlan('harvest').crew_visits_used,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]}))};}
 const ids=[...derivedPlan('metro').items];return {spend:derivedPlan('metro').spend,visits:derivedPlan('metro').crew_visits_used,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]}))};}
const radio = (name,val,label,on) => `<label class="sw"><input type="radio" name="${name}" value="${val}" ${on?'checked':''}> ${label}</label>`;
function switches(op){const M=OPS[op].t.portfolio_constraints;
 if(op==='lakeside')return `<fieldset class="switch"><legend>Budget for November and December</legend>${radio('sw-budget',5000,usd(5000),LS.budget===5000)}${radio('sw-budget',6500,usd(6500),LS.budget===6500)}</fieldset><fieldset class="switch"><legend>Cooperative extends its letter of intent past 30 Nov</legend>${radio('sw-loi','yes','Yes',LS.loi)}${radio('sw-loi','no','No',!LS.loi)}<small>The rice huller needs inverter 2 working and 5 working days to connect.</small></fieldset>`;
 if(op==='harvest')return `<fieldset class="switch"><legend>Aggregator signs the off-season contract</legend>${radio('sw-agg','yes','Yes',LS.agg)}${radio('sw-agg','no','No',!LS.agg)}<small>Budget ${usd(M.budget_usd_nov_dec)} for November and December.</small></fieldset>`;
 return `<fieldset class="switch"><legend>Embakasi’s time-of-use and demand-charge tariff applies (to confirm from the utility invoice)</legend>${radio('sw-tou','yes','Yes',LS.tou)}${radio('sw-tou','no','No',!LS.tou)}<small>Budget ${usd(M.budget_usd_nov_dec)} for November and December.</small></fieldset>`;}
function meter(label,used,capv,fmt){const p=Math.min(100,used/capv*100);return `<div class="meter"><div class="meterhead"><span>${label}</span><strong>${fmt(used)} of ${fmt(capv)}</strong></div><div class="metertrack" role="img" aria-label="${label}: ${fmt(used)} of ${fmt(capv)}"><span style="width:${p}%"></span></div></div>`;}
function actFirstScreen(){const op=LS.op,o=OPS[op],A=o.t.portfolio.allocation,M=o.t.portfolio_constraints,P=planCase(op),budget=op==='lakeside'?LS.budget:M.budget_usd_nov_dec,crew=derivedPlan(op).crew_visits_limit;
 const rows=P.ids.map(id=>{const x=OPT[id],[cv,cn]=optCost(x),[ev,en]=PLAN_EFFECT[id]?PLAN_EFFECT[id]():optEffect(x),d=DEC_SEE_ALSO[id]||decOf(id).id;
  return [`${siteLink(x._site)}`,`<b>${optLabel(id)}</b>`,WHY_FIRST[id]||'',id==='MTO-METER-AUDIT'?`${usd(OPT['MTO-METER-AUDIT'].cost)} <small class="cellnote">routine maintenance budget</small>`:`${fig(`opt:${id}:cost`,cv)} <small class="cellnote">${whoPays(x)}</small>`,VISIT[id]?.[0]?.()||'—',`${ev} <small class="cellnote">${en}</small>${ec(id==='MTO-BILLING'?'ECONOMIC_ACTUAL_FORWARD':id==='BAT-EVIDENCE'?'EXPOSURE':optClass(x))}${DV_OPT[id]?dvTag(DV_OPT[id]):''}`,fx(x.condition)||'—',link(`decision/${d}`,'Decision →')];});
 const say=op==='lakeside'?`Plan re-computed: spend ${usd(P.spend)}, modelled 12-month change ${usd(P.value,true)}.`:`Plan re-computed: spend ${usd(P.spend)}.`;
 let excl=[];
 if(op==='lakeside'){excl=A.excluded.filter(x=>!['MTO-INV-BUYNOW'].includes(x.id)).map(x=>[x.id,fx(x.reason)]);if(P.lose)excl.unshift([P.lose.id,P.loseAffordable?`Under this assumption it gives ${usd(P.lose.value,true)} against ${usd(P.win.value,true)}`:`Needs ${usd(P.lose.spend)} with everything else; the budget is ${usd(budget)}`]);if(!P.huller)excl.unshift(['MTO-HULLER',cap(hullerCell(inv0(P.c)))]);}
 else if(op==='harvest'){excl=A.excluded.map(x=>[x.id,fx(OPT[x.id].reason)||fx(x.reason)]);if(!LS.agg)excl.unshift(['MWEA-AGG','The aggregator does not sign: Mwea stays at no action']);}
 else {excl=['EMB-CHEAPEST','KAS-OEM-WAIT','KAS-LOCAL','KAS-SCHEDULE','RUI-ABSORB10','RUI-4CHARGERS'].map(id=>[id,fx(OPT[id].reason)]);excl.push(['RUI-CONN-CLAIM','Deferred to the next routine visit: no departure depends on it']);if(!LS.tou)excl.unshift(['EMB-DEADLINE','Flat tariff: the schedule change saves nothing and is not recommended']);}
 const L=A.listed_not_summed;
 const listed=op==='lakeside'?[['Charges restored at Mto (12 months)',fig('stake:charges',usd(L['MTO-BILLING_charges_12m'])),'ECONOMIC_ACTUAL_FORWARD','Billed, not yet collected'],['Possible Kisiwa service credit',fig('stake:credit',usd(L['KIS-OM-SLA_potential_credit'])),'EXPOSURE','Counted only when a credit note arrives'],['Kobo battery cover',fig('stake:battery',usd(L['BAT-001_cover_exposure'])),'EXPOSURE','Protected, not gained']]
  :op==='harvest'?[['Thika French-bean batch (B-1031) exposed on 6 Oct',fig('stake:batch',usd(siteM('thika').incident.batches[0].exposed_value)),'EXPOSURE',`The customer’s produce; only the ${usd(SN('thika').liability)} downgrade became a liability`],['Insurance reimbursement','$0','RECORDED',`Not claimed: ${usd(SN('thika').liability)} is below the ${usd(siteM('thika').incident.insurance.deductible)} deductible`]]
  :[[`Ruiru purchase avoided by taking ${num(DOPT('RUI-ABSORB6').params.added_buses)} buses`,fig('opt:RUI-ABSORB6:effect',usd(OPT['RUI-ABSORB6'].avoided_capex)),'MODELLED','Avoided capital, not a saving in the books'],['Kasarani penalties so far in November',fig('stake:penalty',usd(KN().penalties)),'DERIVED','Already incurred; not reversed by the plan'],['Possible Kasarani service credit if the repair is late',SCREDIT(siteM('kasarani').entitlement.contracts[1].service_credit),'EXPOSURE','Counted only on a credit note']];
 const total=op==='lakeside'?`<div class="total"><span>Modelled 12-month change from the valued options, not realised</span><strong>${fig('port:lakeside:m12',usd(P.value,true))}</strong><small>${valueNote(op,P)} Each valued option changes a different factor, so each is counted once. ${dvTag()} for the generator stop setting and the rice huller.</small><p class="downside">${downside(op)}</p></div>`
  :op==='harvest'?`<div class="total"><span>Modelled 12-month change from the valued options, not realised</span><strong>${usd(harvestValue(),true)}</strong><small>${valueNote(op,P)} ${dvTag('Assumption: Kirinyaga recovery share 80%, range 60–90%')}.</small><p class="downside">${downside(op)}</p></div>`
  :`<div class="total"><span>Modelled 12-month change from the valued options, not realised</span><strong>${derivedPlan('metro').value?usd(derivedPlan('metro').value,true):'$0'}</strong><small>${valueNote(op,P)} ${dvTag()} (schedule feasibility, ${num(DOPT('EMB-DEADLINE').params.feasible_nights)} of ${num(SN('embakasi').nights_in_period)} nights).</small><p class="downside">${downside(op)}</p></div>`;
 const paths=op==='lakeside'?sec('Two ways to restore Mto’s inverter, under this assumption',`<div class="paths">${[P.win,P.lose].filter(Boolean).map((x,i)=>`<div class="path ${i===0?'win':''}"><div class="eyebrow">${i===0?'In the plan':'Competing path'}</div><h3>${optLabel(x.id)}</h3>${kv([['Plan spend',usd(x.spend)],['Modelled 12-month change from the valued options',usd(x.value,true)],['Inverter back',fdate(DOPT(x.id).restore_date)],['Rice huller',x.huller?'Kept':cap(hullerCell(x.id))],['Fits the budget',x.spend<=budget?'Yes':'No']])}</div>`).join('')}</div><p class="note">${mtoCapacityLine()}</p>`,'Both paths shown side by side; the plan picks the better one that fits.'):'';
 const fieldRows=P.ids.map(id=>[VISIT[id]?.[1]==='field'?'Field work':VISIT[id]?.[1]==='contractor'?'Contractor':'Remote or office',`${SK[OPT[id]._site].name}: ${optLabel(id)}`,VISIT[id]?.[0]?.()||'—']).sort((a,b)=>a[0].localeCompare(b[0]));
 return `<div class="grid2 controls"><div>${switches(op)}<p id="plan-live" class="vh" role="status" aria-live="polite" data-say="${escapeHtml(say)}"></p></div><div>${meter('Budget used',P.spend,budget,usd)}${meter(cap(o.crewWord)+' used',P.visits,crew,num)}${op==='harvest'&&!LS.agg?'':''}</div></div>
 ${sec('The plan for November and December',region('Recommended set',table(['Site','What','Reason it comes first','Cost · who pays','Crew or technician','12-month result · evidence','Condition',''],rows))+total,`One search over all the decisions together: one option for each, within the budget, ${o.crewWord}, deadlines and dependencies. An option that breaks a hard limit is left out unless no option can keep it. The plan breaks the limits least, then is worth most, then spends least.`)}
 ${paths}
 <div class="grid2">${sec('Crew visits and remote changes',region('Crew visits and remote changes',table(['Kind','Work','Who'],fieldRows)))}${sec('Listed beside the plan, not added',region('Listed beside the plan',table(['Item','Amount','Evidence','Why it is not added'],listed.map(([a,b,c,d])=>[a,b,ec(c),d]))))}</div>
 ${sec('Excluded or deferred, and why',region('Excluded options',table(['Option','Site','Reason'],excl.map(([id,r])=>[link(`decision/${DEC_SEE_ALSO[id]||decOf(id).id}`,optLabel(id)),SK[OPT[id]._site].name,r]))))}
 ${op==='lakeside'?sec('All four cases of the two switches',region('Four cases',table(['Budget','Letter extended','Inverter path','Rice huller','Spend','Modelled 12-month change'],Object.entries(DERIVED.plans['lakeside-power'].switch_cases).map(([k,c])=>{const [b,l]=k.split('/');return [usd(+b),l==='True'?'Yes':'No',optLabel(inv0(c)),c.items.includes('MTO-HULLER')?'Kept':'Lost',usd(c.spend),usd(c.value,true)];}))),'More budget never lowers the result; whether the letter is extended is what changes the path.'):''}`;}

/* ---------- Outcomes by site: each outcome's factor structure by site ---------- */
function lensGrid(op){const o=OPS[op];
 const cell=(sk,l)=>{const out=[];walk(tree(sk),n=>{if(n.lens===l&&(n.eff&&Math.abs(n.eff)>0.004||n.bound&&n.bound.state!=='ok'||n.residual))out.push(n);});
  if(l==='assure'){const est=[];walk(tree(sk),n=>{if(n.cls==='ESTIMATED'&&!n.kids)est.push(n);});
   if(!out.length&&!est.length)return '<span class="muted">All factors observed; nothing estimated</span>';
   return [...out.map(n=>`${n.label}${n.eff!=null?` (${usd(n.eff,true)})`:''}`),...est.map(n=>`${n.label}: estimated`)].join('<br>');}
  if(l==='protect')return protectCell(op,sk);
  if(l==='protect-old'){const b=[];walk(tree(sk),n=>{if(n.bound&&n.lens==='protect')b.push(`${n.label}: ${BOUND[n.bound.state][0].toLowerCase()}`);});const ob=out.filter(n=>!n.bound).map(n=>`${n.label} (${usd(n.eff,true)})`);return [...b,...ob].join('<br>')||'<span class="muted">No limit at risk</span>';}
  const top=out.filter(n=>!n.kids||n.kids.every(k=>!(k.lens===l&&k.eff)) ).sort((a,b)=>Math.abs(b.eff||0)-Math.abs(a.eff||0)).slice(0,2);
  if(o.kind==='cost'&&l==='grow')return sk==='ruiru'?'Room for 6 more buses on existing chargers':'<span class="muted">Not applicable: cost centre</span>';
  return top.length?top.map(n=>`${n.label} (${usd(n.eff,true)})`).join('<br>'):'<span class="muted">On plan</span>';};
 return region('Site by outcome grid',`<table class="lgrid"><thead><tr><th>Site</th>${Object.values(LENS).map(([n])=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${o.sites.map(sk=>`<tr><th scope="row">${siteLink(sk)}<small>${usd(siteM(sk).period.variance,true)} against plan</small></th>${Object.keys(LENS).map(l=>`<td>${cell(sk,l)}</td>`).join('')}</tr>`).join('')}</tbody></table>`);}
function waterfall(op){const o=OPS[op],T=opTotals(op),cost=o.kind==='cost';let run=T.plan;const rows=[{label:'Plan',total:true,from:0,to:run,v:run}];
 o.sites.forEach(sk=>{walk(tree(sk),n=>{const leafEff=n.eff!=null&&!n.obs&&(n.evd||n.residual)&&!(n.kids||[]).some(k=>k.evd);if(!leafEff||Math.abs(n.eff)<0.004)return;const amt=cost?-n.eff:n.eff;rows.push({site:sk,label:n.label,from:run,to:r2(run+amt),v:amt,cls:n.cls,res:n.residual,resLabel:n.resLabel,key:n.evd||`node:${sk}:${n.id}`});run=r2(run+amt);});});
 rows.push({label:'October',total:true,from:0,to:run,v:run});
 const max=Math.max(...rows.map(r=>Math.max(r.from,r.to)))*1.04,min=Math.min(0,...rows.map(r=>Math.min(r.from,r.to)));const sc=v=>(v-min)/(max-min)*100;
 const worse=v=>cost?v>0:v<0;
 return `<figure class="wf" aria-labelledby="wf-t"><figcaption id="wf-t"><strong>From plan to October ${cost?'cost':'contribution'}: the deviation attributed to factors</strong> · one view of the structure below. Solid bars are recorded or calculated, hatched are modelled splits, dashed are not explained by the model yet.</figcaption>
 <div class="wfrows">${rows.map(r=>{const a=sc(Math.min(r.from,r.to)),w=Math.max(Math.abs(sc(r.to)-sc(r.from)),0.6);const tone=r.total?'total':worse(r.v)?'worse':'better',pat=r.res?'res':CLS[r.cls]?.[1]==='mod'?'mod':'';
  const inner=`<span class="wflabel">${r.site?`<small>${SK[r.site].name}</small>`:''}${r.label}</span><span class="wftrack" aria-hidden="true"><span class="wfbar ${tone} ${pat}" style="left:${a}%;width:${w}%"></span></span><span class="wfval">${usd(r.v,!r.total)}${r.total?'':`<small>${r.res?(r.resLabel||'not explained by the model yet'):ecw(r.cls)}</small>`}</span>`;
  return r.total?`<div class="wfrow total">${inner}</div>`:`<button class="wfrow" data-evd="${r.key}" aria-label="${escapeHtml(`${SK[r.site].name}, ${r.label}: ${usd(r.v,true)}, ${r.res?(r.resLabel||'not explained by the model yet'):ecw(r.cls)}. Show how this is worked out`)}">${inner}</button>`;}).join('')}</div>
 <details class="astable"><summary>Show as a table</summary>${region('Waterfall as a table',table(['Site','Factor','Amount','Evidence'],rows.filter(r=>!r.total).map(r=>[SK[r.site].name,r.label,usd(r.v,true),r.res?cap(r.resLabel||'not explained by the model yet'):ecw(r.cls)])))}</details></figure>`;}
function outcomesBySiteScreen(){const op=LS.op,o=OPS[op],T=opTotals(op),res=residualOf(op);
 return `<p class="lede">Each site’s ${o.kind==='cost'?'cost per required departure':'contribution'} is computed from its declared factors. The plan is the same structure on planned factors, so every deviation sits at the factor where it arises; a residual appears only where a leaf factor is not observed.</p>
 ${sec(`${o.name}: ${o.kind==='cost'?'cost':'contribution'} = Σ of the three sites`,region('Portfolio composition',table(['Site',o.kind==='cost'?'Plan cost':'Plan','October','Deviation',op==='metro'?'Of which not attributed yet':'Of which not explained by the model yet'],[...o.sites.map(sk=>{let r=0;walk(tree(sk),n=>{if(n.residual&&n.eff!=null)r+=n.eff;});const P=siteM(sk).period;return [siteLink(sk),usd(o.kind==='cost'?P.plan.total:P.plan.contribution),fig(`node:${sk}:root`,usd(o.kind==='cost'?P.actual.total:P.actual.contribution)),usd(P.variance,true),usd(r2(r),true)];}),[`<b>Portfolio</b>`,`<b>${usd(T.plan)}</b>`,`<b>${fig(`port:${op}:actual`,usd(T.actual))}</b>`,`<b>${usd(T.variance,true)}</b>`,`<b>${usd(res.residual,true)}</b>`]])))}
 ${sec('Outcomes by site',lensGrid(op),'Each cell names the factor behind that outcome at that site. Select a site to open its structure.')}
 ${sec('Operations measures by site, against plan',opsTable(op),'Operational productivity as measured factors; portfolio values composed as Σ ÷ Σ, never an average of site percentages.')}
 ${sec('Protect: measures by site against their target',protectTable(op),'Protect is its own structure of measured factors: units, period, target 0, evidence class, Σ over sites. Money-valued measures are the same factor as their cost line.')}
 ${sec('Deviation attributed to factors',waterfall(op))}
 ${o.sites.map(sk=>sec(`${SK[sk].name} · ${SK[sk].type}`,factorTable(sk),`${tree(sk).label} = ${tree(sk).how}. Plan against October at every factor, with the evidence class in words.`,link(`site/${sk}`,'Open site →'),`fs-${sk}`)).join('')}`;}

/* ---------- Opportunity ---------- */
function opportunityScreen(){const op=LS.op;
 if(op==='lakeside'){const hu=OPT['MTO-HULLER'],w=OPT['MTO-WELDING'],k=siteM('kobo').daytime_headroom;
  return `${sec('Demand that adds contribution, ranked',region('Qualified demand',table(['Rank','Customer and site','Evidence of demand','Load','Net a month','12 months','Feasibility',''],[['1',`Mto Farmers Cooperative · ${siteLink('mto')}`,'Signed letter of intent, lapses 30 Nov',`${hu.load.kw} kW, ${hu.load.window}, ${hu.load.days_per_month} days (${num(hu.load.kwh_month)} kWh)`,fig('opt:MTO-HULLER:effect',usd(hu.economics.net_monthly,true))+ec('MODELLED'),usd(DOPT('MTO-HULLER').value,true)+` after ${usd(DOPT('MTO-HULLER').net_one_off)} connection`,`After inverter 2 is restored; ${hu.forward_replay.days_without_headroom} low-sun days a month need ${num(hu.forward_replay.kwh_from_battery_or_genset)} kWh from battery or generator`,link('decision/mto-demand','Decision →')]])))}
  ${sec('When the loads would run',hourStrip([[hu.load.window,'Rice huller (daytime, solar)','good'],[w.load.window,'Welding (evening, diesel)','bad']]),'Daytime load uses spare solar; evening load runs on diesel. A text list follows the chart.')}
  ${sec('Rejected demand, with break-even',region('Rejected demand',table(['Customer and site','Evidence','Net a month','Break-even','Reason'],[[`Evening welding workshop · ${siteLink('mto')}`,'Verbal enquiry, no contract',usd(w.economics.net_monthly,true)+ec('MODELLED'),`$${w.break_even_tariff_usd_per_kwh} a kWh (tariff $0.40)`,fx(w.reason)]])))}
  ${sec('Capacity without a customer',`<div class="capbox"><b>Kobo: ${k.usable_kw} kW of daytime solar, ${k.window}</b><p>Seen in the earlier five-day study (the daytime headroom finding). No customer has asked for it, so it is shown as capacity, never as an opportunity value. A signed customer would make it a demand factor and open a decision.</p>${link('opportunity-finding','Open the headroom study →')}</div>`)}`;}
 if(op==='harvest'){const ag=OPT['MWEA-AGG'],capc=null; /* per room below */
  return `${sec('Demand that adds contribution, ranked',region('Qualified demand',table(['Rank','Customer and site','Evidence of demand','Volume','Net a month','Over the contract','Feasibility',''],[['1',`Mwea Horticulture Aggregators · ${siteLink('mwea')}`,'Draft contract, not signed',`${num(ag.economics.crate_days_month/30)} crates, Dec–Mar, at ${usd2(ag.economics.revenue_monthly/ag.economics.crate_days_month)} (${num(ag.economics.crate_days_month)} crate-days a month)`,fig('opt:MWEA-AGG:effect',usd(ag.economics.net_monthly,true))+ec('MODELLED'),usd(DOPT('MWEA-AGG').value,true)+` after ${usd(DOPT('MWEA-AGG').net_one_off)} set-up`,'Avocado with cabbage needs an ethylene curtain and a shared 5 °C setpoint',link('decision/mwea-occupancy','Decision →')]])))}
  ${sec('Rejected demand','<p class="note">No demand was rejected in this period.</p>')}
  ${sec('Capacity without a customer',region('Idle capacity',table(['Room','Capacity','Occupied','Idle crate-days','Evidence'],OPS.harvest.sites.map(sk=>{const a=siteM(sk).period.actual;return [siteLink(sk),num(CAPCD(sk)),num(a.crate_days),num(CAPCD(sk)-a.crate_days),ec('DERIVED')];})))+'<p class="note">Idle capacity is capacity, not value; only a customer makes it a demand factor.</p>')}`;}
 const a6=OPT['RUI-ABSORB6'],a10=OPT['RUI-ABSORB10'],ru=siteM('ruiru');const cur=ru.physical.buses*ru.physical.kwh_per_bus_night;
 return `${notice('Captive fleet: charging earns no revenue. The opportunity is more service from the same chargers.','blue')}
 ${sec('More service from the same chargers',region('Service options',table(['Option','Required a night','Deliverable a night','Capital','Result',''],[[`${optLabel('RUI-ABSORB6')} · ${siteLink('ruiru')}`,`${num(a6.required_kwh)} kWh`,`${num(a6.deliverable_kwh)} kWh`,'$0',`Feasible; avoids a ${fig('opt:RUI-ABSORB6:effect',usd(a6.avoided_capex))} purchase ${ec('MODELLED')}`,link('decision/ruiru-expansion','Decision →')]])))}
 ${sec('Ruiru: required against deliverable energy a night',capBars([[`Today (${ru.physical.buses} buses)`,cur],['6 more buses',a6.required_kwh],['10 more buses',a10.required_kwh]],a6.deliverable_kwh),`Today’s figure is ${ru.physical.buses} buses × ${ru.physical.kwh_per_bus_night} kWh. A text list follows the chart.`)}
 ${sec('Rejected',region('Rejected service options',table(['Option','Reason'],[[optLabel('RUI-ABSORB10'),fx(a10.reason)],[optLabel('RUI-4CHARGERS'),fx(OPT['RUI-4CHARGERS'].reason)]])))}
 ${sec('Capacity without a customer',`<p class="prose">Ruiru’s chargers were in use ${pct(ru.period.actual.charger_hour_utilisation)} of nameplate charger-hours in October, but used ${ruiruDeliverable()} of the energy deliverable a night: the 400 kW import limit binds, not the chargers. That is capacity; the city’s offer is what turns part of it into service.</p>`)}`;}
function hourStrip(items){const pos=w=>{const [a,b]=w.split('-');const h=t=>{const [x,y]=t.split(':').map(Number);return x+y/60;};return [h(a)/24*100,(h(b)-h(a))/24*100];};
 return `<figure class="hours"><div class="hscale" aria-hidden="true">${[0,6,12,18,24].map(h=>`<span style="left:${h/24*100}%">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${items.map(([w,l,t])=>{const [x,wd]=pos(w);return `<div class="hrow"><span class="hlab">${l}</span><span class="htrack" aria-hidden="true"><span class="hsolar"></span><span class="hbar ${t}" style="left:${x}%;width:${wd}%"></span></span></div>`;}).join('')}<p class="note">Shaded band: daylight hours. </p><ul class="list">${items.map(([w,l])=>`<li>${l}: ${w.replace('-','–')}</li>`).join('')}</ul></figure>`;}
function capBars(items,limit){const max=Math.max(limit,...items.map(i=>i[1]))*1.08;return `<figure class="capbars">${items.map(([l,v])=>`<div class="cbrow"><span class="cblab">${l}</span><span class="cbtrack" aria-hidden="true"><span class="cbbar ${v>limit?'over':''}" style="width:${v/max*100}%"></span><span class="cblimit" style="left:${limit/max*100}%"></span></span><span class="cbval">${num(v)} kWh</span></div>`).join('')}<p class="note">Vertical line: ${num(limit)} kWh deliverable a night at the ${num(SN('ruiru').import_limit_kw)} kW import limit.</p><ul class="list">${items.map(([l,v])=>`<li>${l}: ${num(v)} kWh a night, ${v>limit?'above':'within'} ${num(limit)} kWh</li>`).join('')}</ul></figure>`;}

