function COMMIT_OF(op){const st=OPT['KOB-STOPSOC'],hu=OPT['MTO-HULLER'],mb=OPT['MTO-BILLING'],kr=OPT['KIRI-REPAIR'],ag=OPT['MWEA-AGG'],dl=OPT['EMB-DEADLINE'],ks=DOPT('KIS-REPAIR');
 return {
 lakeside:[['kobo-generator','Kobo: stop the generator at 70% battery',`Candidate running litres down as predicted on the decision page; battery at least 35% at 5 am every day; ${usd(st.economics.net_monthly,true)} a month`,'Trial not started (as of 6 Nov)'],['kisiwa-genset','Kisiwa: repair generator 1',`Two generators available every evening from ${fdate(ks.restore_date)}; repair at ${usd(ks.operator_one_off)}`,'Repair booked'],['mto-demand','Mto: connect the rice huller',`${num(hu.load.kwh_month)} kWh a month billed at ${usd2(OPS.lakeside.t.prices.productive_tariff_usd_per_kwh)}; ${usd(hu.economics.net_monthly,true)} a month net`,'Waiting for inverter 2'],['mto-billing','Mto: fix the meter records',`${num(siteM('mto').period.actual.unbilled_mapping_kwh)} kWh a month billed (${usd(mb.economics.charges_monthly)} a month in charges)`,'Records fix in progress']],
 harvest:[['kirinyaga-energy','Kirinyaga: clean the condenser and repair the leak',`Electricity above the model down by ${pct(kr.recovery_share)} (range ${pct(kr.recovery_range[0])}–${pct(kr.recovery_range[1])}): ${usd(kr.economics.monthly,true)} a month`,'Repair not done yet'],['thika-backup','Thika: start controller replaced under warranty, night cover until then','Automatic start works in the witnessed start test; no compensation credit notes',`Replacement scheduled ${fdate(siteM('thika').entitlement.remedy_scheduled)}`],['mwea-occupancy','Mwea: aggregator contract',`${num(ag.economics.crate_days_month)} crate-days a month December to March; ${usd(ag.economics.net_monthly,true)} a month net`,'Contract not signed']],
 metro:[['embakasi-schedule','Embakasi: charge to each bus’s departure time',`Peak share ${pct(+M.evaluation.options['EMB-DEADLINE'].changes.peak_kwh)}; about ${num(DOPT('EMB-DEADLINE').params.max_kw_option*DOPT('EMB-DEADLINE').params.hours_after_midnight*SN('embakasi').nights_in_period)} kWh a month at the 00:00–05:00 rate; peak at most ${dl.max_kw} kW; every departure met; ${usd(dl.economics.saving_monthly)} a month below no action`,'Schedule not started'],['kasarani-charger','Kasarani: one bus charged at Ruiru each night until the repair',`Every departure met to ${fdate(DOPT('KAS-OEM-STOPGAP').restore_date)}; charger 2 restored by ${fdate(DOPT('KAS-OEM-STOPGAP').restore_date)}; penalties avoided ${usd(DOPT('KAS-OEM-STOPGAP').monthly_or_horizon_change)}`,'Cover from 6 Nov'],['ruiru-expansion','Ruiru: take 6 more buses',`All departures met (${num(DOPT('RUI-ABSORB6').bound.required_kwh_night)} of ${num(DOPT('RUI-ABSORB6').bound.deliverable_kwh_night)} kWh a night); peak import under ${siteM('ruiru').physical.import_limit_kw} kW`,'Awaiting the city’s contract']]}[op];}
const COMMIT=new Proxy({},{get:(_,op)=>COMMIT_OF(op)});
function whatChangedScreen(){const op=LS.op;
 const rows=COMMIT[op].map(([d,what,pred,state])=>[link(`decision/${d}`,what),pred+ec('MODELLED'),state,badge('Not yet','amber'),badge('Not yet','amber'),badge('Not yet','amber')]);
 const rt=RIGHTS_OF_OP[op].map(k=>{const r=rightsOf(k),cur=STAGE_IX[r.state];return [link(`decision/${r.dec}`,r.asset),r.type,`<span class="ministeps" aria-label="Stage ${cur+1} of 8: ${cur>=0?STAGES[cur]:'no claim stage'}">${STAGES.map((st,i)=>`<i class="${i<=cur?'on':''}" title="${st}"></i>`).join('')}</span><small class="cellnote">${cur>=0?STAGES[cur]:'No claim possible'}${r.stopped?' · '+r.stopped:''}</small>`,r.deadline?`${fdate(r.deadline)} <small class="cellnote">${daysUntil(r.deadline)} days</small>`:'—',r.cost,'None'];});
 return `${sec('Actions: what was chosen, its frozen prediction and three verdicts',region('Actions',table(['Action (the chosen option)','Frozen prediction','State','Operational verdict: factor moved, limits held','Economic verdict: money moved','Causal verdict: strength of attribution'],rows))+'<p class="note">Each chosen option is tracked here as an Action from the moment it is chosen. Each verdict is separate. Not proven yet is a verdict, not a pass; a prediction is never relabelled as realised.</p>')}
 ${sec('Rights measures by contract and period (as of 6 Nov)',rightsMeasures(op))}
 ${sec('Rights tracker',region('Rights tracker',table(['Asset or contract','Type','State','Deadline','Our cost','Money recorded'],rt))+'<p class="note">Every state is set by a person from a recorded document or event. Money is recorded only when a credit note or receipt arrives.</p><p class="legal">This is not a legal decision. Coverage is decided by the supplier or insurer.</p>')}`;}

