const MISSING_LEAVES = {
 lakeside:[['All sites','Usable capacity by time window','Energy management export by time window','The idle-capacity leak and any value of daytime headroom'],['Kobo','Battery cell temperature','Battery management system temperature log','A battery warranty claim'],['Kobo','Commissioning capacity test','Capacity test record (planned battery capacity test)','A battery warranty claim'],['Kisiwa','October maintenance-contract invoice','Service contractor invoice','The actual maintenance-contract line (carried at plan) and the service-credit review'],['All sites','Plan split of litres by reason','Plan at sub-factor level','Plan comparison below total litres (the split is compared with zero)']],
 harvest:[['Thika','October refrigeration service invoice','Service contractor invoice','The actual maintenance line (carried at plan)'],['All rooms','Compatibility per batch (unbilled or incompatible occupancy)','Storage ledger with commodity and segregation fields','The occupied-to-chargeable leak (assumed zero now)']],
 metro:[['Kasarani','October maintenance invoice','Service contractor invoice','The actual maintenance line (carried at plan)'],['Ruiru','Plan split by time of day','Plan at sub-factor level',`Attribution of the ${usd(residualOf('metro').residual)} difference`],['Embakasi','Tariff applicability','Utility invoice with time-of-use lines','The schedule recommendation becoming unconditional'],['Embakasi, Kasarani','Deliverable energy a night (depot model)','Charger and import-limit configuration per depot','The deliverable-energy stage of the chain']]};
