const MOVE = {kobo:'kobo-generator',kisiwa:'kisiwa-genset',mto:'mto-inverter',mwea:'mwea-occupancy',thika:'thika-backup',kirinyaga:'kirinyaga-energy',embakasi:'embakasi-schedule',kasarani:'kasarani-charger',ruiru:'ruiru-expansion'};
function sitesScreen(){const op=LS.op,o=OPS[op];
 const rows=o.sites.map(sk=>{const P=siteM(sk).period,t=tree(sk),a=ATTN[op].find(r=>r[2]===sk),d=decById(MOVE[sk]),rec=d.opts.find(id=>OPT[id].disposition==='RECOMMENDED');
  const res=o.kind==='cost'?`${usd2(t.actual)} a departure <small class="cellnote">plan ${usd2(t.plan)} · cost ${usd(P.actual.total)} against ${usd(P.plan.total)}</small>`:`${usd(P.actual.contribution)} <small class="cellnote">plan ${usd(P.plan.contribution)} · ${usd(P.variance,true)}</small>`;
  return [`${siteLink(sk)}<small class="cellnote">${SK[sk].type}</small>`,res,a?`<span class="attn-k attn-${a[0]}">${a[1]}</span> ${a[3]}`:'—',link(`decision/${d.id}`,optLabel(rec))];});
 return `${notice(`Sites of ${o.name}, the demo operator selected in the review bar.`,'blue')}${sec(`${o.name} · ${o.sites.length} sites`,region('Site directory',table(['Site',o.kind==='cost'?'Cost per required departure met':'Contribution against plan','Factor needing attention','Recommended move'],rows)),'October 2026')}`;}

/* ---------- Financials root: the operator's economic statement ---------- */
function financialsScreen(){const op=LS.op,o=OPS[op],T=opTotals(op);
 const lines=[];o.sites.forEach(sk=>walk(tree(sk),(n,d)=>{if(n.unit==='$'&&!n.obs&&d<=3&&(n.plan!=null||n.actual!=null)&&!n.evd)lines.push([sk,n,d]);}));
 const rows=lines.map(([sk,n,d])=>[d===0?siteLink(sk):'',`<span class="fac" style="--d:${d}"><b>${n.label}</b></span>`,n.plan!=null?usd(n.plan):'<span class="muted">not declared</span>',n.actual!=null?fig(`node:${sk}:${n.id}`,usd(n.actual)):'—',n.eff!=null?usd(n.eff,true):'—',ec(n.cls)]);
 const P=o.t.portfolio;let ratio;
 if(o.vertical==='mini')ratio=[['Cost to serve per billed kWh',`${usd(P.chain.cost_to_serve)} ÷ ${num(P.chain.billed_kwh)} kWh = $${(P.chain.cost_to_serve/P.chain.billed_kwh).toFixed(4)}`,`${usd(P.chain.plan_cost_to_serve)} ÷ ${num(P.chain.plan_billed_kwh)} kWh = $${(P.chain.plan_cost_to_serve/P.chain.plan_billed_kwh).toFixed(4)}`]];
 else if(o.vertical==='cold'){const e=o.sites.reduce((a,sk)=>a+siteM(sk).period.actual.energy,0),pe=o.sites.reduce((a,sk)=>a+siteM(sk).period.plan.energy,0);ratio=[['Electricity per occupied crate-day',`${usd(e)} ÷ ${num(P.chain.occupied_crate_days)} = $${(e/P.chain.occupied_crate_days).toFixed(4)}`,`${usd(pe)} ÷ ${num(P.chain.plan_crate_days)} = $${(pe/P.chain.plan_crate_days).toFixed(4)}`]];}
 else ratio=[['Cost per required departure met',`${usd(P.actual_cost)} ÷ ${num(P.departures_met)} = ${usd2(P.cost_per_departure_actual)}`,`${usd(P.plan_cost)} ÷ ${num(P.departures_required)} = ${usd2(r2(P.plan_cost/P.departures_required))}`]];
 return `${sec(`${o.name} · economic statement, October 2026`,region('Economic statement',table(['Site','Money factor','Plan','October','Effect','Evidence'],[...rows,['<b>Portfolio</b>',`<b>${o.kind==='cost'?'Charging and depot cost':'Contribution'}</b>`,`<b>${usd(T.plan)}</b>`,`<b>${fig(`port:${op}:actual`,usd(T.actual))}</b>`,`<b>${usd(T.variance,true)}</b>`,ec('RECORDED')]])),`Every site’s money factors against plan, with the evidence class in words. ${pct(P.coverage.cost_recorded_share,1)} of cost on recorded facts.`)}
 ${sec('Portfolio ratios, composed as Σ ÷ Σ',region('Portfolio ratios',table(['Ratio','October','Plan'],ratio))+'<p class="note">Portfolio ratios are the sum of numerators over the sum of denominators of comparable sites, never an average of site percentages. A site without the record is excluded and named, never counted as zero.</p>')}
 ${sec('Site economics',`<ul class="list">${o.sites.map(sk=>`<li>${link(`site/${sk}/economics`,`${SK[sk].name} economics`)}: every factor against plan, the prices and models used, and the decisions that change them</li>`).join('')}</ul>`)}`;}
